using Panissimo.Domain.Common;
using Panissimo.Domain.Inventory;

namespace Panissimo.Domain.Production;

/// <summary>Order line an OP serves (RN-71). <see cref="ParentOrder"/> is plan-only: it is never linked.</summary>
public enum DemandType
{
    BranchOrderLine,
    CustomerOrderLine,
    ParentOrder,
}

/// <summary>
/// Informative link between an OP generated by the plan and the order line that originated it (RN-71, RN-72).
/// It reserves nothing: cancelling the OP leaves the order as it is.
/// </summary>
public class ProductionOrderDemand : Entity
{
    private ProductionOrderDemand() { }

    public ProductionOrderDemand(Guid productionOrderId, DemandType demandType, Guid demandLineId, decimal quantity)
    {
        if (demandType == DemandType.ParentOrder)
            throw new ArgumentException("Only order lines are linked to a production order.", nameof(demandType));
        ProductionOrderId = productionOrderId;
        DemandType = demandType;
        DemandLineId = demandLineId;
        Quantity = quantity;
    }

    public Guid ProductionOrderId { get; private set; }
    public DemandType DemandType { get; private set; }
    public Guid DemandLineId { get; private set; }
    public decimal Quantity { get; private set; }
}

/// <summary>One unit of demand for a product: an order line or the requirement of a parent OP (RN-70).</summary>
/// <param name="Date">Day it counts in the plan: its required (or scheduled) date, or the first day if earlier.</param>
public sealed record PlanDemand(
    Guid ItemId,
    DemandType Type,
    Guid SourceLineId,
    Guid DocumentId,
    string Folio,
    string PartyName,
    DateOnly RequiredDate,
    decimal Quantity);

/// <summary>Pending production of an open OP; it covers from its ScheduledDate on.</summary>
public sealed record PlanSupply(Guid ItemId, DateOnly ScheduledDate, decimal Quantity);

/// <param name="Multiple">ProductionMultiple (RN-70 rounds up to it).</param>
/// <param name="WholeQuantities">Base unit in pieces (RN-03b).</param>
/// <param name="MinQty">Plant minimum, if configured.</param>
public sealed record PlanItemInput(
    Guid ItemId,
    decimal Stock,
    decimal Multiple,
    bool WholeQuantities,
    decimal? MinQty,
    decimal? MaxQty,
    IReadOnlyList<PlanDemand> Demands,
    IReadOnlyList<PlanSupply> Supplies);

/// <param name="StockReplenishment">Stock to keep (MaxQty) when the plant would end below its minimum; first day only.</param>
/// <param name="StartingStock">Projected stock at the start of the day (after previous days and suggestions).</param>
/// <param name="OpenOrders">Pending of OPs covering from this day.</param>
public sealed record PlanDay(
    Guid ItemId,
    DateOnly Date,
    decimal BranchOrders,
    decimal CustomerOrders,
    decimal StockReplenishment,
    decimal ParentOrders,
    decimal StartingStock,
    decimal OpenOrders,
    decimal SuggestedQty,
    IReadOnlyList<PlanDemand> DemandLines)
{
    public decimal TotalDemand => BranchOrders + CustomerOrders + StockReplenishment + ParentOrders;
}

/// <summary>
/// RN-70: net demand per product and day, cumulative. Stock covers the closest days first; an open OP covers from its
/// ScheduledDate (earlier ones from the first day; later than the range, never); what is suggested for a day counts as
/// covered for the next ones. Stock replenishment: if the projected stock at the end of the range stays below the minimum,
/// the first day also asks for the maximum as stock to keep. Shortfalls round up to the production multiple.
/// </summary>
public static class ProductionPlanCalculator
{
    public static IReadOnlyList<PlanDay> Calculate(PlanItemInput item, DateOnly from, DateOnly to)
    {
        if (to < from)
            throw new ArgumentException("The plan range ends before it starts.", nameof(to));

        var demands = item.Demands.Where(d => d.RequiredDate <= to && d.Quantity > 0).ToList();
        var supplies = item.Supplies.Where(s => s.ScheduledDate <= to && s.Quantity > 0).ToList();

        var replenishment = 0m;
        if (item.MinQty is { } min && item.MaxQty is { } max)
        {
            var projected = Walk(item, demands, supplies, from, to, 0).Final;
            // The walk's "available" is stock left over after the demand; holding MaxQty back on the first day makes the
            // suggestions end the range with the maximum in stock.
            if (projected < min)
                replenishment = max;
        }
        return Walk(item, demands, supplies, from, to, replenishment).Days;
    }

    /// <summary>Rounds a shortfall up to the multiple (and to whole pieces).</summary>
    public static decimal RoundUp(decimal shortfall, decimal multiple, bool wholeQuantities)
    {
        if (shortfall <= 0)
            return 0;
        var step = multiple > 0 ? multiple : 1;
        var qty = decimal.Ceiling(shortfall / step) * step;
        if (wholeQuantities)
            qty = decimal.Ceiling(qty);
        return InventoryMath.Round(qty);
    }

    private static (List<PlanDay> Days, decimal Final) Walk(PlanItemInput item, List<PlanDemand> demands, List<PlanSupply> supplies,
        DateOnly from, DateOnly to, decimal replenishment)
    {
        var days = new List<PlanDay>();
        var available = item.Stock;
        for (var date = from; date <= to; date = date.AddDays(1))
        {
            var day = date;
            bool CountsToday(DateOnly d) => d == day || (day == from && d < from);

            var dayDemands = demands.Where(d => CountsToday(d.RequiredDate)).OrderBy(d => d.RequiredDate).ThenBy(d => d.Folio).ToList();
            var openOrders = supplies.Where(s => CountsToday(s.ScheduledDate)).Sum(s => s.Quantity);
            var branch = dayDemands.Where(d => d.Type == DemandType.BranchOrderLine).Sum(d => d.Quantity);
            var customer = dayDemands.Where(d => d.Type == DemandType.CustomerOrderLine).Sum(d => d.Quantity);
            var parent = dayDemands.Where(d => d.Type == DemandType.ParentOrder).Sum(d => d.Quantity);
            var stockTarget = day == from ? replenishment : 0;

            var starting = available;
            available += openOrders - branch - customer - parent - stockTarget;
            var suggested = available < 0 ? RoundUp(-available, item.Multiple, item.WholeQuantities) : 0;
            available += suggested;

            if (branch + customer + parent + stockTarget + openOrders + suggested > 0)
                days.Add(new PlanDay(item.ItemId, day, branch, customer, stockTarget, parent, starting, openOrders, suggested, dayDemands));
        }
        return (days, available);
    }
}
